package com.joaoeoneves.fintrack.domain.model

import java.time.LocalDate

/** How a goal's target is read: per calendar year, or as one total to reach. */
enum class GoalTargetType { ANNUAL, TOTAL }

/**
 * A savings goal, which is also a savings plan: it may own one hidden expense recurring item ([recurringId])
 * that is its monthly contribution. A [targetCents] of 0 means "no target". Money counts towards it
 * when it comes from an expense generated by one of the [linkedRecurringIds] (a standing order into savings
 * or investments) or filed under [linkedCategoryId].
 * [targetType] ANNUAL counts the current calendar year; TOTAL counts everything from [startDate] plus
 * [initialCents], and may have a [targetDate] to pace itself against. A blank [id] means "not saved yet".
 */
data class SavingsGoal(
    val id: String,
    val name: String,
    val targetCents: Long,
    val targetType: GoalTargetType,
    val startDate: LocalDate,
    val targetDate: LocalDate? = null,
    val initialCents: Long = 0L,
    val linkedRecurringIds: Set<String> = emptySet(),
    val linkedCategoryId: CategoryId? = null,
    val archived: Boolean = false,
    val order: Int = 0,
    val recurringId: String? = null,
) {
    /** Every recurring item whose expenses count: the linked ones plus the plan's own [recurringId]. */
    val countedRecurringIds: Set<String> get() = linkedRecurringIds + listOfNotNull(recurringId)
}
